package app.yoru.mobile;

import android.app.*;
import android.view.*;
import android.widget.*;
import java.text.*;
import java.util.*;

public final class CalendarScreen extends ScrollView {
    private final Activity activity;private final LinearLayout body,dayRow,filterRow,list;private final TextView state,heroTitle,heroMeta;private final ArrayList<ApiRepository.AiringItem> items=new ArrayList<>();private final Locale ru=new Locale("ru");private int selected;private String filter="all";private boolean attached;
    public CalendarScreen(Activity a){super(a);activity=a;attached=true;setFillViewport(true);body=Ui.column(a);body.setPadding(Ui.dp(a,18),Ui.dp(a,14),Ui.dp(a,18),Ui.dp(a,30));addView(body,new ScrollView.LayoutParams(-1,-2));body.addView(Ui.label(a,"КАЛЕНДАРЬ YORU"));Ui.space(body,11);body.addView(Ui.text(a,"Выход серий",29,Ui.TEXT,true));Ui.space(body,9);body.addView(Ui.text(a,"Онгоинги, премьеры и ближайшие серии с точными датами выхода, когда они доступны.",12,Ui.MUTED,false));Ui.space(body,17);LinearLayout hero=Ui.column(a);hero.setPadding(Ui.dp(a,18),Ui.dp(a,18),Ui.dp(a,18),Ui.dp(a,18));hero.setBackground(Ui.gradient(0xff2e2140,0xff181220,20,a));heroTitle=Ui.text(a,"Загружаем расписание…",21,Ui.TEXT,true);hero.addView(heroTitle);Ui.space(hero,8);heroMeta=Ui.text(a,"Собираем ближайшие даты выхода",12,0xffd8c7ea,false);hero.addView(heroMeta);Ui.space(hero,13);hero.addView(Ui.button(a,"Обновить календарь",false,this::load));body.addView(hero,Ui.lp(a,-1,-2));Ui.space(body,17);HorizontalScrollView days=new HorizontalScrollView(a);days.setHorizontalScrollBarEnabled(false);dayRow=Ui.row(a);days.addView(dayRow);body.addView(days,Ui.lp(a,-1,-2));Ui.space(body,10);HorizontalScrollView filters=new HorizontalScrollView(a);filters.setHorizontalScrollBarEnabled(false);filterRow=Ui.row(a);filters.addView(filterRow);body.addView(filters,Ui.lp(a,-1,-2));Ui.space(body,14);state=Ui.text(a,"",12,Ui.MUTED,false);body.addView(state);Ui.space(body,12);list=Ui.column(a);body.addView(list);load();}
    @Override protected void onAttachedToWindow(){super.onAttachedToWindow();attached=true;}
    @Override protected void onDetachedFromWindow(){attached=false;super.onDetachedFromWindow();}
    private void load(){state.setText("Обновляем календарь…");heroTitle.setText("YORU следит за неделей");heroMeta.setText("Точные даты показываются сразу, недостающие появляются как аккуратный прогноз.");list.removeAllViews();progressCard();YoruApp.app().io.execute(()->{try{ArrayList<ApiRepository.AiringItem> loaded=YoruApp.app().api.airingSchedule(21);YoruApp.app().main.post(()->{if(!alive())return;items.clear();items.addAll(loaded);selected=0;renderDays();renderFilters();renderList();});}catch(Exception e){YoruApp.app().main.post(()->{if(!alive())return;items.clear();renderDays();renderFilters();list.removeAllViews();state.setText("Не удалось получить расписание. Сервис календаря временно недоступен — попробуйте обновить позже.");emptyCard("Календарь временно недоступен","Каталог и YORU Source продолжают работать. Нажмите “Обновить календарь”, когда сеть стабилизируется.");});}});}
    private boolean alive(){return attached&&!activity.isFinishing();}
    private void renderDays(){dayRow.removeAllViews();for(int i=0;i<14;i++){final int index=i;TextView chip=Ui.chip(activity,dayTitle(i)+" · "+dayCount(i),i==selected,()->{selected=index;renderDays();renderList();});LinearLayout.LayoutParams p=Ui.lp(activity,-2,-2);p.rightMargin=Ui.dp(activity,7);dayRow.addView(chip,p);}}
    private void renderFilters(){filterRow.removeAllViews();String[][] rows={{"all","Все"},{"fav","Избранное"},{"premiere","Премьеры"},{"film","Фильмы"}};for(String[] r:rows){TextView chip=Ui.chip(activity,r[1],r[0].equals(filter),()->{filter=r[0];renderFilters();renderDays();renderList();});LinearLayout.LayoutParams p=Ui.lp(activity,-2,-2);p.rightMargin=Ui.dp(activity,7);filterRow.addView(chip,p);}}
    private void renderList(){list.removeAllViews();ArrayList<ApiRepository.AiringItem> day=new ArrayList<>();long start=dayStart(selected),end=start+24L*60*60*1000;for(ApiRepository.AiringItem item:items)if(item.time>=start&&item.time<end&&accept(item))day.add(item);String title=day.isEmpty()?"На этот день пока пусто":nearestTitle();heroTitle.setText(title);heroMeta.setText(items.isEmpty()?"Нет данных календаря":items.size()+" событий на ближайшие 3 недели · "+exactCount()+" с точным временем");state.setText(dayTitleLong(selected)+(day.isEmpty()?" · новых серий не найдено":" · событий: "+day.size()));if(day.isEmpty()){emptyCard("Тихий день","Проверьте соседние дни или обновите календарь. У части онгоингов дата может появиться ближе к релизу.");return;}for(int i=0;i<day.size();i++){itemCard(day.get(i),i);}}
    private void itemCard(ApiRepository.AiringItem item,int index){LinearLayout card=Ui.row(activity);card.setGravity(Gravity.CENTER_VERTICAL);card.setPadding(Ui.dp(activity,12),Ui.dp(activity,12),Ui.dp(activity,12),Ui.dp(activity,12));card.setBackground(Ui.stroke(Ui.CARD,16,activity));ImageView poster=new ImageView(activity);poster.setScaleType(ImageView.ScaleType.CENTER_CROP);poster.setBackground(Ui.shape(Ui.SURFACE,12,activity));poster.setClipToOutline(true);card.addView(poster,Ui.lp(activity,54,76));if(item.anime!=null)YoruApp.app().images.load(poster,item.anime);LinearLayout text=Ui.column(activity);text.setPadding(Ui.dp(activity,12),0,0,0);TextView name=Ui.text(activity,item.anime==null?"Аниме":item.anime.title,14,Ui.TEXT,true);name.setMaxLines(2);name.setEllipsize(android.text.TextUtils.TruncateAt.END);text.addView(name);Ui.space(text,6);text.addView(Ui.text(activity,item.kind+" · серия "+item.episode+" · "+time(item.time),11,Ui.PURPLE,true));Ui.space(text,5);text.addView(Ui.text(activity,countdown(item.time)+" · "+item.precision+" · "+item.source,10,Ui.MUTED,false));card.addView(text,new LinearLayout.LayoutParams(0,-2,1));Ui.Icon icon=new Ui.Icon(activity,"play");icon.color=Ui.PURPLE;card.addView(icon,Ui.lp(activity,24,24));Ui.press(card);card.setOnClickListener(v->{if(item.anime!=null)Ui.openDetails(activity,item.anime);});LinearLayout.LayoutParams cp=Ui.lp(activity,-1,-2);cp.bottomMargin=Ui.dp(activity,9);list.addView(card,cp);if(!YoruApp.app().store.liteMode()){card.setAlpha(0f);card.setTranslationY(Ui.dp(activity,10));card.animate().alpha(1f).translationY(0).setStartDelay(Math.min(240,index*28)).setDuration(180).start();}}
    private void progressCard(){LinearLayout c=Ui.column(activity);c.setPadding(Ui.dp(activity,16),Ui.dp(activity,16),Ui.dp(activity,16),Ui.dp(activity,16));c.setGravity(Gravity.CENTER_HORIZONTAL);c.setBackground(Ui.stroke(Ui.CARD,16,activity));ProgressBar bar=new ProgressBar(activity);c.addView(bar,Ui.lp(activity,36,36));Ui.space(c,12);c.addView(Ui.text(activity,"Собираем ближайшие релизы…",12,Ui.MUTED,true));list.addView(c,Ui.lp(activity,-1,-2));}
    private void emptyCard(String title,String message){LinearLayout c=Ui.column(activity);c.setPadding(Ui.dp(activity,16),Ui.dp(activity,16),Ui.dp(activity,16),Ui.dp(activity,16));c.setBackground(Ui.stroke(Ui.CARD,16,activity));c.addView(Ui.text(activity,title,17,Ui.TEXT,true));Ui.space(c,8);c.addView(Ui.text(activity,message,12,Ui.MUTED,false));list.addView(c,Ui.lp(activity,-1,-2));}
    private boolean accept(ApiRepository.AiringItem item){if(item==null||item.anime==null)return false;if("fav".equals(filter))return YoruApp.app().store.favorite(item.anime);if("premiere".equals(filter))return "Премьера".equals(item.kind);if("film".equals(filter))return item.anime.type.toLowerCase(Locale.ROOT).contains("фильм");return true;}
    private int dayCount(int offset){long s=dayStart(offset),e=s+24L*60*60*1000;int n=0;for(ApiRepository.AiringItem item:items)if(item.time>=s&&item.time<e&&accept(item))n++;return n;}
    private int exactCount(){int n=0;for(ApiRepository.AiringItem item:items)if(accept(item)&&("Точная дата".equals(item.precision)||"Премьера".equals(item.precision)))n++;return n;}
    private String nearestTitle(){long now=System.currentTimeMillis();ApiRepository.AiringItem best=null;for(ApiRepository.AiringItem item:items)if(accept(item)&&item.time>=now&&(best==null||item.time<best.time))best=item;if(best==null&&!items.isEmpty())best=items.get(0);return best==null?"Календарь YORU":(best.time<System.currentTimeMillis()?"Уже вышло: ":"Ближайшая серия: ")+(best.anime==null?"аниме":best.anime.title);}
    private long dayStart(int offset){Calendar c=Calendar.getInstance();c.set(Calendar.HOUR_OF_DAY,0);c.set(Calendar.MINUTE,0);c.set(Calendar.SECOND,0);c.set(Calendar.MILLISECOND,0);c.add(Calendar.DAY_OF_YEAR,offset);return c.getTimeInMillis();}
    private String dayTitle(int offset){if(offset==0)return "Сегодня";if(offset==1)return "Завтра";return new SimpleDateFormat("EEE dd.MM",ru).format(new Date(dayStart(offset))).replaceFirst("\\.","");}
    private String dayTitleLong(int offset){return offset==0?"Сегодня":offset==1?"Завтра":new SimpleDateFormat("EEEE, dd MMMM",ru).format(new Date(dayStart(offset)));}
    private String time(long t){return new SimpleDateFormat("HH:mm",ru).format(new Date(t));}
    private String countdown(long t){long diff=t-System.currentTimeMillis();if(diff<=-90*60*1000)return "уже вышло";if(diff<=0)return "выходит сейчас";long min=diff/60000,h=min/60,d=h/24;if(d>0)return "через "+d+" д "+(h%24)+" ч";if(h>0)return "через "+h+" ч "+(min%60)+" мин";return "через "+Math.max(1,min)+" мин";}
}
